using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;
public static class CP6Save {
 [Serializable]class Expected{public string run,region,streams,gear,profile,layout;public int seed;public float cooldown;}
 static string Gear(ThirdPersonHero h)=>string.Join("|",h.GetComponent<AdventureLoadout>().items.Select(g=>g.id).OrderBy(x=>x));
 public static IEnumerator Run(CP6Probe p){yield return p.Wait(()=>GameEntry.Instance!=null,15);var entry=GameEntry.Instance;entry.Refresh();bool resume=entry.Info.canContinue;if(resume)p.Check("resume-normal-continue",entry.Continue(),"genuine synthetic save, original normal entry");else{entry.AskNew();p.Check("save-normal-confirm-new",entry.ConfirmNew(),"actual new-game transaction");}yield return p.Wait(()=>UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Saves?.IsInitialized==true,30);var s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s?.Saves?.IsInitialized!=true)throw new Exception("Save not initialized");if(s.Flow.ActiveRun==null)p.Check("save-real-depart",s.Flow.Depart(AdventureMode.ForestExploration),"normal forest departure");yield return p.Wait(()=>s.WorldReady&&s.Flow.ActiveRun!=null,30);if(!s.WorldReady)throw new Exception("World not ready");foreach(var e in s.enemies){e.enabled=false;var boss=e.GetComponent<ForestBossBrain>();if(boss!=null)boss.enabled=false;}var hero=s.hero;var combat=hero.GetComponent<AdventureCombat>();var run=s.Flow.ActiveRun;
 if(resume){Time.timeScale=0;var expected=JsonUtility.FromJson<Expected>(File.ReadAllText(p.Root+"/expected.json"));p.Check("resume-same-run",run.runId==expected.run&&run.regionInstanceId==expected.region&&run.seed==expected.seed,"Run/region/seed preserved");p.Check("resume-same-random",JsonUtility.ToJson(run.randomStreams)==expected.streams,"all three B3 states preserved");p.Check("resume-same-gear",Gear(hero)==expected.gear,"actual restored item IDs, no duplicated reward");p.Check("resume-profile",JsonUtility.ToJson(s.Flow.Profile)==expected.profile,"warehouse/badges/tutorial and permanent identity unchanged");p.Check("resume-cooldown",combat.SkillRemaining>expected.cooldown-.25f&&combat.SkillRemaining<=expected.cooldown+.01f,"existing v9 shared skill field restored, no new schema");p.Check("resume-no-action-replay",!combat.Expanded.Busy&&combat.Expanded.Selected==0&&combat.PendingAttackCount==0,"selection resets to legacy; pending startup never replayed");var envelope=JsonUtility.FromJson<CombatSaveEnvelope>(File.ReadAllText(s.Saves.SavePath));p.Check("resume-v9",envelope.version==9,"existing version unchanged");yield return p.Wait(()=>false,.4f);Time.timeScale=1;PlayerInput.Focus(true);yield return null;yield return null;p.Check("resume-old-slot-cooldown-shared",!combat.UseSkill()&&combat.SkillRemaining>0&&!hero.GameplayPaused,"restored shared cooldown also gates legacy slot");p.Check("resume-no-pending-artifacts",UnityEngine.Object.FindObjectsByType<SkillImpactField>().Length==0&&UnityEngine.Object.FindObjectsByType<SkillPiercingProjectile>().Length==0,"no phantom new skill entities");yield break;}
 combat.Gear.SelectMain(combat.Gear.items.First(g=>g.type==GearType.Sword&&g.InBag));combat.Expanded.Select(2);PlayerInput.Focus(true);yield return new WaitForSeconds(.3f);bool released=false;combat.Expanded.Observed+=e=>{if(e.stage=="release")released=true;};p.Check("save-real-new-skill-start",combat.UseSkill(),"real skill consumes configured cooldown");p.Check("save-during-startup",combat.Expanded.Busy&&!released,"before first release");p.Check("save-existing-transaction",s.Saves.SaveProgress(false),"unmodified atomic v9 writer");var disk=JsonUtility.FromJson<CombatSaveEnvelope>(File.ReadAllText(s.Saves.SavePath));p.Check("save-v9",disk.version==9,"no added progress schema");var expectedState=new Expected{run=run.runId,region=run.regionInstanceId,seed=run.seed,streams=JsonUtility.ToJson(run.randomStreams),gear=Gear(hero),profile=JsonUtility.ToJson(s.Flow.Profile),cooldown=combat.SkillRemaining};File.WriteAllText(p.Root+"/expected.json",JsonUtility.ToJson(expectedState,true));var package=p.Root+"/SeedPackage";Directory.CreateDirectory(package);foreach(var f in Directory.GetFiles(Path.GetDirectoryName(s.Saves.SavePath)))File.Copy(f,Path.Combine(package,Path.GetFileName(f)),false);combat.CancelPending();p.Check("save-cancel-no-damage",!released&&!combat.Expanded.Busy&&combat.SkillRemaining>0,"no refund or deferred release after save");
 }
}
